#!/usr/bin/env python3
import pathlib, sys
root=pathlib.Path(sys.argv[1] if len(sys.argv)>1 else '.').resolve()

def read(rel): return (root/rel).read_text(encoding='utf-8')
def write(rel,s): (root/rel).write_text(s,encoding='utf-8')
def once(s,old,new,label):
    c=s.count(old)
    if c!=1: raise SystemExit(f'TT051_PREDIST_APPLY_{label}:{c}')
    return s.replace(old,new,1)

SETPIECE="function makeSetPieceWindow(session,sourceEvent,kind,team){const s=session.state,id=`SP${String((s.counters.setPieceWindows||0)+1).padStart(4,'0')}`;s.counters.setPieceWindows=(s.counters.setPieceWindows||0)+1;return{id,type:'SET_PIECE_2D_WINDOW',sceneId:id,atSecond:s.second,sourceEventId:sourceEvent.id,reason:`SET_PIECE_${kind}`,setPiece:{kind,team,lane:s.ball.lane,progress:s.ball.progress},heroPlayerId:heroId(session),heroRole:session.opts.heroRole||'CM',heroTeam:session.opts.heroTeam||'HOME',stateSnapshot:{second:s.second,score:{...s.score},possession:team,zone:s.zone,phase:s.phase,danger:s.danger,ball:{...s.ball,team},structure:deep(s.structure)},preContext:causalContext(s,8),futureOutcomePrecomputed:false,choicePrecomputed:false};}\n"
