OLD_SHOT=" // Only non-promoted low-resolution play may resolve a shot. Once a 2D window opens, no future is computed here.\n if(s.ball.progress>.84&&nextRandom(session)<.04+s.danger*.07){const q=clamp(.2+s.danger*.62+(nextRandom(session)-.5)*.22,.05,.95),priorOwner=s.ball.ownerId,shooter=pickActor(session,team,s,'SHOT');if(shooter===heroId(session)){s.ball.ownerId=priorOwner;const trigger={id:`HERO-FINISH-${String((s.counters.heroFinishingWindows||0)+1).padStart(4,'0')}`,t:s.second,kind:'HERO_FINISHING_WINDOW'};s.counters.heroFinishingWindows=(s.counters.heroFinishingWindows||0)+1;s.danger=Math.max(s.danger,q);return promoteFromStepStart(session,prePromotion,trigger,'ATTACKING_INVOLVEMENT');}s.ball.ownerId=shooter;s.counters.shots++;const shot=addEvent(session,'SHOT',team,{actorId:shooter,actorRole:roleOf(shooter),quality:q,fromZone:s.zone});if(nextRandom(session)<q*.24){s.score[team]++;s.counters.goals++;s.teams[team].score=s.score[team];addEvent(session,'GOAL',team,{actorId:shooter,actorRole:roleOf(shooter),quality:q,score:{...s.score},fromShot:shot.id});s.ball.progress=.5;s.zone='MIDFIELD';s.phase='BUILD_UP';s.danger=.08;s.possession=opp;s.ball.team=opp;s.ball.ownerId=opp==='HOME'?'H-CM':'A-CM';}else{const outcomeRoll=nextRandom(session);if(outcomeRoll<.17&&s.second-session.lastSetPieceAt>70){const ce=addEvent(session,'CORNER',team,{actorId:shooter,actorRole:roleOf(shooter),quality:q,fromShot:shot.id,lane:s.ball.lane});session.lastSetPieceAt=s.second;s.ball.team=team;s.ball.ownerId=shooter;s.ball.progress=.96;s.zone='BOX';s.phase='CHANCE';s.danger=.62;return makeSetPieceWindow(session,ce,'CORNER',team);}const saved=outcomeRoll<.63,outcome=addEvent(session,saved?'SAVE':'SHOT_MISSED',team,{actorId:shooter,actorRole:roleOf(shooter),quality:q,fromShot:shot.id});s.possession=opp;s.ball.team=opp;s.ball.progress=saved?.14:.08;s.zone=zoneFromProgress(s.ball.progress);s.phase='BUILD_UP';s.danger=.07;s.ball.ownerId=opp==='HOME'?'H-GK':'A-GK';if(saved&&(session.opts.heroRole||'CM')==='GK'&&opp===(session.opts.heroTeam||'HOME'))return makeWindow(session,outcome,'GK_DISTRIBUTION');}}\n"
NEW_SHOT=" // A non-hero shot is never resolved in low resolution. V0.6 computes the real outcome; UI only replays it when it becomes a goal.\n if(s.ball.progress>.84&&nextRandom(session)<.04+s.danger*.07){const q=clamp(.2+s.danger*.62+(nextRandom(session)-.5)*.22,.05,.95),priorOwner=s.ball.ownerId,shooter=pickActor(session,team,s,'SHOT');if(shooter===heroId(session)){s.ball.ownerId=priorOwner;const trigger={id:`HERO-FINISH-${String((s.counters.heroFinishingWindows||0)+1).padStart(4,'0')}`,t:s.second,kind:'HERO_FINISHING_WINDOW'};s.counters.heroFinishingWindows=(s.counters.heroFinishingWindows||0)+1;s.danger=Math.max(s.danger,q);return promoteFromStepStart(session,prePromotion,trigger,'ATTACKING_INVOLVEMENT');}s.ball.ownerId=shooter;s.danger=Math.max(s.danger,q);return makeNonHeroShotWindow(session,team,shooter,q);}\n"
AUTH_FN="function runNonHeroShotWindow(boundary,opts={}){const env=seedMatch(boundary,{...opts,explicitHeroChoiceRequired:true}),{E,P,state}=env,frames=[deep(E.snapshot(state.m))],start=state.m.time,duration=clamp(Number(opts.durationSeconds)||8,5,10),hero=state.heroPlayerId,shotter=boundary.shot?.shooterId||boundary.stateSnapshot?.ball?.ownerId;state.mode='FULL_SKIP';const sp=state.m.playersById?.[shotter]||state.m.players.find(p=>p.id===shotter);if(sp){sp.nextThink=state.m.time+.02;sp.controlledSince=Math.min(Number(sp.controlledSince||state.m.time),state.m.time-.6);}let guard=0,shotSeen=false,resolved=false;while(!state.m.completed&&!state.pending&&state.m.time<start+duration-.001&&guard++<2200){if(tryHeroOwnerCheckpoint(P,state))break;P.step(state,.10);frames.push(deep(E.snapshot(state.m)));if(tryHeroOwnerCheckpoint(P,state))break;const ev=(state.m.events||[]).filter(e=>e.t>=start-.001);shotSeen=shotSeen||ev.some(e=>['SHOT','HEADER_SHOT'].includes(e.type));resolved=ev.some(e=>['GOAL','SAVE','CHIP_SAVE','SHOT_MISSED','BLOCK','CORNER','GOAL_KICK'].includes(e.type));if(shotSeen&&resolved&&state.m.time>start+1.0)break;}const snapshot=E.snapshot(state.m),events=(state.m.events||[]).filter(e=>e.t>=start-.001).map(deep),pending=state.pending?deep(state.pending):null,scene=state.currentScene?deep(state.currentScene):null;if(!pending){const bad=events.find(e=>e.actorId===hero&&['SHOT','HEADER_SHOT','GOAL','PASS','TAKE_ON'].includes(e.type));if(bad)throw new Error(`UNCHOSEN_PROTAGONIST_NON_HERO_SHOT_ACTION_FORBIDDEN:${bad.type}:${hero}`);}return{...env,frames,snapshot,actualEvents:events,pending,scene,hadChoice:!!pending,result:null,searchSeconds:Number((snapshot.time-start).toFixed(3)),preSpan:Number((snapshot.time-start).toFixed(3)),futureOutcomePrecomputed:false};}\n"
UI_BRANCH='  if(r.boundary?.type===\'NON_HERO_SHOT_2D_WINDOW\'){\n    opened=A.runNonHeroShotWindow(r.boundary,{seed:`${seed()}-${r.boundary.sceneId}-SHOT`,durationSeconds:8});\n    if(opened.pending){session=opened.state;selectedStepResults=[];const rep=P.latestReplay(session);$(\'heroEventLog\').innerHTML+=`<div class="major-match-event"><strong>${Math.floor(r.boundary.atSecond/60)+1}\' · 비주인공 슈팅 흐름에서 주인공 선택 발생</strong> · AI 행동 전에 사용자 선택으로 전환</div>`;phase=\'SCENE_NOTICE\';showSceneNotice(`${periodMinute(session.m.time)} · 슈팅 흐름에서 주인공 선택 상황`,()=>{if(phase===\'SCENE_NOTICE\')startReplay(rep,\'CHOICE\',\'슈팅 흐름 → 선택 직전 실제 경기\')});return true}\n    const hb=ensureScoreEventIntegrity(opened.entrySnapshot?.score||r.boundary.stateSnapshot?.score,{snapshot:opened.snapshot,hadChoice:false,result:null,actualEvents:opened.actualEvents||[],episodeFrames:opened.frames||[]}),goal=(hb.actualEvents||[]).find(e=>e.type===\'GOAL\');\n    if(goal){deferredHandback=hb;hb.entrySnapshot=deep(opened.entrySnapshot);const frames=causalFramesForEvent(opened.frames,goal.t,8,3.5),who=goal.team===(world.opts?.heroTeam||\'HOME\')?\'우리 팀 득점\':\'상대 팀 득점\';$(\'heroEventLog\').innerHTML+=`<div class="major-match-event"><strong>⚽ ${Math.floor(goal.t/60)+1}\' · ${who}</strong> · 실제 V0.6 득점 과정 2D 표시</div>`;startReplay(frames,\'NOCHOICE_HANDOFF\',`${who} · 실제 득점 과정`);return true}\n    appendHighResNotables(hb.actualEvents||[]);H.resumeFromHighRes(world,hb);flushHybridNotables();beforeHybrid=null;activeBoundary=null;opened=null;return false;\n  }\n'
UI_FN="async function openGitHubBugIssue(){const d=currentDebugForBug();if(!d)return;const desc=$('heroBugDescription').value.trim();if(!desc){$('heroBugDescription').focus();return;}const cat=$('heroBugCategory').value,prio=$('heroBugPriority').value,snap=compactBugSnapshot(d),endpoint=String(window.FLR_BUG_REPORT_ENDPOINT||'').trim(),button=$('heroBugOpenIssue')||$('heroBugSubmit');if(button){button.disabled=true;button.textContent=endpoint?'버그 등록 중…':'등록 서버 확인 중…';}\n  try{if(!endpoint)throw new Error('BUG_REPORT_ENDPOINT_MISSING');const rid=`tt051-${crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`}`,payload={reportId:rid,build:'TT-0.51',step:78,category:cat,priority:Number(prio),description:desc,summary:snap,debug:d,client:{userAgent:navigator.userAgent,href:location.href}},r=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),j=await r.json().catch(()=>({}));if(!r.ok||!j.ok||!j.jsonUrl)throw new Error(j.error||`HTTP ${r.status}`);closeBugModal();const msg=`버그 등록 완료 · ${j.reportId||rid}${j.issueUrl?' · GitHub Issue 자동 생성됨':' · GitHub 로그인 불필요'}`;$('heroPlayback').textContent=msg;pushLiveFeed(msg,'scene');if(j.issueUrl)console.info('FLR bug issue',j.issueUrl);return;}\n  catch(err){console.warn('FLR anonymous bug report failed',err);const u=bugFallbackUrl(desc,cat,prio,snap,d);$('heroPlayback').textContent='자동 등록 실패 · 전체 JSON을 클립보드에 복사했습니다.';window.open(u,'_blank','noopener');}\n  finally{if(button){button.disabled=false;button.textContent='버그 등록';}}\n}"
WORKER='const json=(data,status=200,extra={})=>new Response(JSON.stringify(data),{status,headers:{\'content-type\':\'application/json; charset=utf-8\',...extra}});\nfunction cors(origin,env){const allowed=(env.ALLOWED_ORIGIN||\'https://1lisam.github.io\').split(\',\').map(x=>x.trim());return allowed.includes(origin)?{\'access-control-allow-origin\':origin,\'access-control-allow-methods\':\'POST,OPTIONS\',\'access-control-allow-headers\':\'content-type\',\'vary\':\'Origin\'}:{};}\nfunction validId(v){return typeof v===\'string\'&&/^[a-zA-Z0-9-]{12,80}$/.test(v)}\nfunction cleanText(v,n){return String(v||\'\').replace(/\\s+/g,\' \').trim().slice(0,n)}\nasync function createGitHubIssue(env,p,jsonUrl,sizeBytes){if(!env.GITHUB_ISSUE_TOKEN)return null;const owner=env.GITHUB_OWNER||\'1Lisam\',repo=env.GITHUB_REPO||\'FLR_TEST\',prio=Math.max(1,Math.min(5,Number(p.priority)||3)),cat=cleanText(p.category,40)||\'기타\',desc=String(p.description||\'\').trim(),summary=p.summary||{},sec=summary?.s?.[0],minute=Number.isFinite(sec)?Math.floor(sec/60)+1:\'?\',choiceId=summary?.c?.[0]||\'-\',targetId=summary?.c?.[1]||\'-\',short=cleanText(desc,64)||\'bug report\',title=`[${cleanText(p.build,24)||\'FLR\'}][P${prio}][${cat}] ${short}`,body=`### 사용자 설명\\n${desc}\\n\\n### 자동 첨부\\n- 버전: ${cleanText(p.build,40)} USER_VISUAL_RETEST\\n- 경기 시각: ${minute}분\\n- 분류: ${cat}\\n- 중요도: P${prio}\\n- 선택: ${choiceId} → ${targetId}\\n- **전체 통합 JSON 원본:** ${jsonUrl}\\n- JSON 크기: ${(sizeBytes/1024).toFixed(1)} KiB\\n\\n> 비로그인 테스터가 FLR 버그 리포트에서 직접 전송한 보고서입니다.`,res=await fetch(`https://api.github.com/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}/issues`,{method:\'POST\',headers:{\'accept\':\'application/vnd.github+json\',\'authorization\':`Bearer ${env.GITHUB_ISSUE_TOKEN}`,\'content-type\':\'application/json\',\'user-agent\':\'FLR-Bug-Reporter\',\'x-github-api-version\':\'2022-11-28\'},body:JSON.stringify({title,body})});if(!res.ok){console.error(JSON.stringify({event:\'github_issue_failed\',status:res.status,reportId:p.reportId}));return null;}const out=await res.json();return{issueNumber:out.number,issueUrl:out.html_url};}\nexport default {async fetch(request,env){const u=new URL(request.url),origin=request.headers.get(\'origin\')||\'\',ch=cors(origin,env);if(request.method===\'OPTIONS\')return new Response(null,{status:204,headers:ch});\n  if(request.method===\'GET\'&&u.pathname.startsWith(\'/reports/\')){const key=u.pathname.slice(1),obj=await env.BUG_REPORTS.get(key);if(!obj)return new Response(\'Not found\',{status:404});return new Response(obj.body,{headers:{\'content-type\':\'application/json; charset=utf-8\',\'cache-control\':\'public, max-age=31536000, immutable\',\'content-disposition\':`inline; filename="${key.split(\'/\').at(-1)||\'FLR_BUG_REPORT.json\'}"`}});}\n  if(request.method===\'GET\'&&u.pathname.startsWith(\'/report-meta/\')){const reportId=u.pathname.slice(\'/report-meta/\'.length);if(!validId(reportId))return json({ok:false,error:\'invalid report id\'},400);const obj=await env.BUG_REPORTS.get(`meta/${reportId}.json`);if(!obj)return json({ok:false,error:\'not found\'},404);return new Response(obj.body,{headers:{\'content-type\':\'application/json; charset=utf-8\',\'cache-control\':\'no-store\'}});}\n  if(request.method!==\'POST\'||u.pathname!==\'/report\')return json({ok:false,error:\'not found\'},404,ch);\n  if(!ch[\'access-control-allow-origin\'])return json({ok:false,error:\'origin not allowed\'},403,ch);\n  const len=Number(request.headers.get(\'content-length\')||0);if(len>8_000_000)return json({ok:false,error:\'report too large\'},413,ch);\n  let p;try{p=await request.json()}catch{return json({ok:false,error:\'invalid json\'},400,ch)}\n  if(!validId(p.reportId)||!p.debug||typeof p.description!==\'string\'||!p.description.trim())return json({ok:false,error:\'invalid report\'},400,ch);\n  const reportId=p.reportId,build=String(p.build||\'UNKNOWN\').replace(/[^A-Za-z0-9._-]+/g,\'_\'),key=`reports/${build}/${reportId}.json`,metaKey=`meta/${reportId}.json`,raw=JSON.stringify(p.debug),sizeBytes=new TextEncoder().encode(raw).byteLength;\n  if(sizeBytes>7_500_000)return json({ok:false,error:\'debug json too large\',sizeBytes},413,ch);\n  const existing=await env.BUG_REPORTS.get(metaKey);if(existing){const meta=await existing.json();return json({ok:true,deduplicated:true,...meta},200,ch);}\n  await env.BUG_REPORTS.put(key,raw,{httpMetadata:{contentType:\'application/json\'},customMetadata:{reportId,build,sizeBytes:String(sizeBytes)}});\n  const publicUrl=`${u.origin}/${key}`,reportUrl=`${u.origin}/report-meta/${reportId}`,baseMeta={reportId,jsonUrl:publicUrl,reportUrl,sizeBytes,build,createdAt:new Date().toISOString(),category:cleanText(p.category,80),priority:Math.max(1,Math.min(5,Number(p.priority)||3)),description:String(p.description).trim().slice(0,4000),summary:p.summary||null};\n  const issue=await createGitHubIssue(env,p,publicUrl,sizeBytes).catch(err=>{console.error(JSON.stringify({event:\'github_issue_exception\',reportId,error:String(err)}));return null;});const meta={...baseMeta,issueCreated:!!issue,...(issue||{})};await env.BUG_REPORTS.put(metaKey,JSON.stringify(meta),{httpMetadata:{contentType:\'application/json\'}});\n  return json({ok:true,...meta},201,ch);\n}};\n'
README='# FLR Bug Report Worker\n\nFootball Life RPG의 전체 통합 Episode JSON과 테스터 설명을 Cloudflare R2에 저장하는 익명 버그 접수 Worker입니다.\n\n## Current flow\n1. 사용자가 경기 화면에서 `버그 리포트 등록`을 누릅니다.\n2. 브라우저가 현재 Episode의 전체 통합 JSON + 분류/중요도/설명을 Worker `/report`로 POST합니다.\n3. Worker가 원본 디버그 JSON을 R2 `BUG_REPORTS` binding (`flr-bug-reports`)에 그대로 저장합니다.\n4. Worker가 보고서 메타데이터(설명/분류/중요도/원본 JSON URL)를 UUID 기반 메타 레코드에 저장합니다.\n5. 브라우저는 `버그 등록 완료`를 표시하고 종료합니다. 정상 경로에서는 GitHub 로그인이나 GitHub Issue 작성 화면이 필요하지 않습니다.\n6. `GITHUB_ISSUE_TOKEN`이 Worker secret으로 설정된 경우에만 서버가 같은 보고서를 GitHub Issue로 추가 생성할 수 있습니다. 토큰이 없어도 익명 버그 접수는 정상 완료됩니다.\n7. Worker 접수 자체가 실패한 경우에만 기존 수동 GitHub Issue + 클립보드 JSON fallback을 사용합니다.\n\n## Security / credentials\n- 브라우저에 GitHub token이나 Cloudflare token을 넣지 않습니다.\n- 익명 R2 접수에는 GitHub 자격증명이 필요하지 않습니다.\n- 선택적 자동 GitHub Issue 생성은 Worker secret `GITHUB_ISSUE_TOKEN`을 사용하며, 소스/브라우저에 포함하지 않습니다.\n- Cloudflare 배포 자동화에는 GitHub Actions secrets `CLOUDFLARE_API_TOKEN`과 `CLOUDFLARE_ACCOUNT_ID`를 사용합니다.\n- Worker CORS는 기본적으로 `https://1lisam.github.io`만 허용합니다.\n- 원본 JSON URL과 report-meta URL은 무작위 reportId를 포함하며, report-meta 응답은 `no-store`입니다.\n\n## Cloudflare resources\n- Worker name: `flr-bug-reporter`\n- R2 binding: `BUG_REPORTS`\n- R2 bucket: `flr-bug-reports`\n- Wrangler config: `bug-report-worker/wrangler.toml`\n\n배포가 완료되면 자동화가 workers.dev URL의 `/report` endpoint를 루트 `bug_report_config.js`의 `FLR_BUG_REPORT_ENDPOINT`에 기록합니다.\n'
OLD_IDX='등록 버튼을 누르면 현재 Episode의 전체 통합 JSON 원본을 자동 저장하고 GitHub Issue에 링크합니다. 서버가 아직 연결되지 않았거나 업로드에 실패하면 기존 수동 GitHub 등록 방식으로 안전하게 전환됩니다.'
NEW_IDX='등록 버튼을 누르면 현재 Episode의 전체 통합 JSON 원본과 설명을 서버에 자동 저장합니다. 테스터는 GitHub 로그인이 필요하지 않습니다. 서버에 GitHub 이슈 작성 권한이 연결된 경우 이슈도 자동 생성됩니다.'

